#include "TextureDocument.hh"
#include <cassert>
#include <iostream>
int main(){using namespace bts;SceneSnapshot scene;ImportSummary imported;for(unsigned uid:{1,2}){MaterialSummary m;m.session_id=uid;m.name="Set"+std::to_string(uid);m.uniform_editable=true;scene.materials.push_back(m);imported.materials.push_back({uid,m.name});}TextureDocument doc({},imported,scene);auto &source=doc.set(1),&destination=doc.set(2);TextureDocument::set_resolution(destination,128);TextureDocument::add_mask(source,.1);auto &mask=*source.layers[0].mask;mask.author_resolution=256;PaintPixels::Stamp stamp{{.5,.5},{.15,0},{0,.15},{}};stamp.channels={false,false,true,false,false};stamp.values.roughness=1;mask.pixels.stamp(256,stamp,source.tiles);MaskEffect effect;effect.enabled=false;effect.colors={{1,0,0}};mask.effects={effect};const auto copy=TextureDocument::copy_mask(source,source.selected_layer);const auto hash=copy.pixels.hash(2);TextureDocument::add_mask(destination,.8);destination.layers[0].mask->enabled=false;const auto source_id=source.selected_layer;TextureDocument::paste_mask(destination,destination.selected_layer,copy);auto &pasted=*destination.layers[0].mask;assert(pasted.pixels.hash(2)==hash&&pasted.author_resolution==256&&pasted.background==.1f&&!pasted.enabled);assert(pasted.effects[0].colors==copy.effects[0].colors&&pasted.effects[0].id!=copy.effects[0].id&&!pasted.effects[0].enabled);assert(pasted.value(64,64,1001,128)> .9);stamp.center={.2,.2};source.layers[0].mask->pixels.stamp(256,stamp,source.tiles);assert(copy.pixels.hash(2)==hash&&pasted.pixels.hash(2)==hash);pasted.pixels.stamp(256,stamp,destination.tiles);assert(copy.pixels.hash(2)==hash);assert(source.selected_layer==source_id);std::vector<TextureSetBinding> bindings;for(const auto &set:doc.texture_sets())bindings.push_back({set.id,set.material_session_uid,set.name});const auto decoded=TextureDocument::from_json(doc.to_json(),bindings);const auto &decoded_mask=*decoded.texture_sets()[1].layers[0].mask;assert(decoded_mask.author_resolution==256&&decoded_mask.background==pasted.background&&decoded_mask.enabled==pasted.enabled&&mask_effects_json(decoded_mask.effects)==mask_effects_json(pasted.effects));auto wrong=copy;stamp.center={1.2,.2};wrong.pixels.stamp(256,stamp,{1002});const auto before=doc.to_json();bool rejected=false;try{TextureDocument::paste_mask(destination,destination.selected_layer,wrong);}catch(const std::invalid_argument &){rejected=true;}assert(rejected&&doc.to_json()==before);std::cout<<"Mask copy snapshot/COW independence, replacement, fresh effect IDs, retained destination toggle, rescaled evaluation, metadata and incompatible-tile strong rejection passed\n";
}
